import assert from 'node:assert/strict'
import { createHash } from 'node:crypto'
import { readFileSync } from 'node:fs'
import { execFileSync } from 'node:child_process'

const hash = value => createHash('sha256').update(value).digest('hex')
const root = '/workspace/pnd-baseline-144-plans'
const base = '79833890f3b3b06f91d0179dcc61cd0e012882ba'
const candidate = '2773eaaa3e325b621bfec003abc49f18929ab6da'
const load = name => {
  const receipt = JSON.parse(readFileSync(`work/orchestration/${name}`, 'utf8'))
  assert.equal(receipt.phase, 'finished')
  assert.deepEqual(receipt.source, receipt.sourceAfter)
  assert.equal(hash(receipt.stdout), receipt.stdoutSha256)
  assert.equal(hash(receipt.stderr), receipt.stderrSha256)
  return receipt
}
const full = load('issue144-plans-focused-2773eaa.json')
const previous = load('issue144-plans-baseline-focused-7983389.json')
assert.equal(full.source.headOid, candidate)
assert.equal(previous.source.headOid, base)
assert.equal(full.status, 'passed')
assert.equal(full.exitCode, 0)
assert.equal(previous.status, 'failed')
assert.equal(previous.exitCode, 1)
assert.deepEqual(full.command, previous.command)
assert.deepEqual(Object.keys(full.source.inputs), Object.keys(previous.source.inputs))
for (const [path, value] of Object.entries(full.source.inputs)) {
  assert.equal(hash(readFileSync(path)), value, path)
  if (path !== 'app/scene-entities.ts') assert.equal(value, previous.source.inputs[path], path)
}
assert.match(full.stdout, /pass 5\n.*fail 0/)
assert.match(previous.stdout, /pass 4\n.*fail 1/)
assert.match(previous.stdout, /64 preparation plans: 2144 ID reads/)
assert.equal(execFileSync('git', ['diff', '--name-only', 'HEAD'], { cwd: root, encoding: 'utf8' }).trim(), '')
assert.equal(previous.source.trackedDiffSha256, hash(''))
const original = execFileSync('git', ['show', `${base}:app/scene-entities.ts`], { encoding: 'utf8' })
assert.equal(hash(original), previous.source.inputs['app/scene-entities.ts'])
assert.equal(hash(readFileSync(`${root}/app/scene-entities.ts`)), previous.source.inputs['app/scene-entities.ts'])
const source = readFileSync('app/scene-entities.ts', 'utf8')
const marker = '  for (const b of scene.world.buildings.filter(b => b.preparation)) {'
const remainder = value => {
  const start = value.indexOf(marker)
  assert.ok(start >= 0)
  return value.slice(start, value.indexOf('\nexport function updateShrinesFrame', start))
}
assert.equal(remainder(source), remainder(original))
const lint = load('issue144-plans-oxlint-2773eaa.json')
const oldLint = load('issue144-plans-baseline-oxlint-7983389.json')
for (const receipt of [lint, oldLint]) {
  assert.equal(receipt.status, 'failed')
  assert.equal(receipt.exitCode, 1)
}
assert.equal(lint.source.headOid, candidate)
assert.equal(oldLint.source.headOid, base)
assert.deepEqual(lint.command, oldLint.command)
for (const [path, value] of Object.entries(lint.source.inputs))
  if (path !== 'app/scene-entities.ts') assert.equal(value, oldLint.source.inputs[path], path)
const diagnostics = receipt => receipt.stdout.trim().split('\n').map(line => line.replace(/:\d+:\d+(?=: (?:warning|error))/, ':<line>:<column>')).sort()
assert.equal(diagnostics(lint).length, 9)
assert.deepEqual(diagnostics(lint), diagnostics(oldLint))
console.log(JSON.stringify({ focusedCandidate: 'passed 5/5', actualUnmodifiedBase: 'failed: four passed, scaling failed at 64 with 2144 ID reads', pairedInputHashes: full.source.inputs, productionBaseUnchanged: true, laterFilterAndBuildingBodyUnchanged: true, strictOxlintCandidate: 'failed', strictOxlintBase: 'failed', diagnosticMultiset: 'passed: nine exact inherited diagnostics; only numeric line/column prefixes normalized', scalingScope: 'preparation-only population and empty completed-building mesh map; completed cleanup remains quadratic' }, null, 2))
